1	/**
2	 * @fileoverview Adapter management REST API routes
3	 *
4	 * This module provides Express routes for managing external adapter plugins:
5	 * - Listing all registered adapters (built-in + external)
6	 * - Installing external adapters from npm packages or local paths
7	 * - Unregistering external adapters
8	 *
9	 * Read-only routes require board org access. Mutating adapter management
10	 * routes require instance-admin access because they can install, reload, or
11	 * toggle server-side adapter code for the whole Paperclip instance.
12	 *
13	 * @module server/routes/adapters
14	 */
15	
16	import { execFile } from "node:child_process";
17	import fs from "node:fs";
18	import { readFile } from "node:fs/promises";
19	import path from "node:path";
20	import { promisify } from "node:util";
21	import { Router } from "express";
22	import {
23	  listServerAdapters,
24	  findServerAdapter,
25	  findActiveServerAdapter,
26	  listEnabledServerAdapters,
27	  registerServerAdapter,
28	  resolveExternalAdapterRegistration,
29	  unregisterServerAdapter,
30	  isOverridePaused,
31	  setOverridePaused,
32	} from "../adapters/registry.js";
33	import {
34	  listAdapterPlugins,
35	  addAdapterPlugin,
36	  removeAdapterPlugin,
37	  getAdapterPluginByType,
38	  getAdapterPluginsDir,
39	  getDisabledAdapterTypes,
40	  setAdapterDisabled,
41	} from "../services/adapter-plugin-store.js";
42	import type { AdapterPluginRecord } from "../services/adapter-plugin-store.js";
43	import type { ServerAdapterModule, AdapterConfigSchema } from "../adapters/types.js";
44	import { loadExternalAdapterPackage, getUiParserSource, getOrExtractUiParserSource, reloadExternalAdapter } from "../adapters/plugin-loader.js";
45	import { logger } from "../middleware/logger.js";
46	import { assertBoardOrgAccess, assertInstanceAdmin } from "./authz.js";
47	import { BUILTIN_ADAPTER_TYPES } from "../adapters/builtin-adapter-types.js";
48	import { forbidden } from "../errors.js";
49	import { expressHandler } from "../http/express-adapter.js";
50	import type { Handler } from "../http/types.js";
51	import type { StorageService } from "../storage/types.js";
52	
53	const execFileAsync = promisify(execFile);
54	
55	// ---------------------------------------------------------------------------
56	// Request / Response types
57	// ---------------------------------------------------------------------------
58	
59	interface AdapterInstallRequest {
60	  /** npm package name (e.g., "droid-paperclip-adapter") or local path */
61	  packageName: string;
62	  /** True if packageName is a local filesystem path */
63	  isLocalPath?: boolean;
64	  /** Target version for npm packages (optional, defaults to latest) */
65	  version?: string;
66	}
67	
68	interface AdapterCapabilities {
69	  supportsInstructionsBundle: boolean;
70	  supportsSkills: boolean;
71	  supportsLocalAgentJwt: boolean;
72	  requiresMaterializedRuntimeSkills: boolean;
73	}
74	
75	interface AdapterInfo {
76	  type: string;
77	  label: string;
78	  source: "builtin" | "external";
79	  modelsCount: number;
80	  loaded: boolean;
81	  disabled: boolean;
82	  capabilities: AdapterCapabilities;
83	  /** True when an external plugin has replaced a built-in adapter of the same type. */
84	  overriddenBuiltin?: boolean;
85	  /** True when the external override for a builtin type is currently paused. */
86	  overridePaused?: boolean;
87	  version?: string;
88	  packageName?: string;
89	  isLocalPath?: boolean;
90	}
91	
92	// ---------------------------------------------------------------------------
93	// Helpers
94	// ---------------------------------------------------------------------------
95	
96	/**
97	 * Resolve the adapter package directory (same rules as plugin-loader).
98	 */
99	function resolveAdapterPackageDir(record: AdapterPluginRecord): string {
100	  return record.localPath
101	    ? path.resolve(record.localPath)
102	    : path.resolve(getAdapterPluginsDir(), "node_modules", record.packageName);
103	}
104	
105	/**
106	 * Read `version` from the adapter's package.json on disk.
107	 * This is the source of truth for what is actually installed (npm or local path).
108	 *
109	 * TODO(cloudflare): readAdapterPackageVersionFromDisk uses fs.readFileSync to
110	 * read package.json from a locally installed npm package directory. The entire
111	 * concept of locally installed adapter packages assumes a persistent filesystem
112	 * and a Node-compatible module loader. For Workers compatibility the installed
113	 * version should be persisted to the database at install time and read from
114	 * there instead of from disk at request time.
115	 */
116	function readAdapterPackageVersionFromDisk(record: AdapterPluginRecord): string | undefined {
117	  try {
118	    const pkgDir = resolveAdapterPackageDir(record);
119	    const raw = fs.readFileSync(path.join(pkgDir, "package.json"), "utf-8");
120	    const v = JSON.parse(raw).version;
121	    return typeof v === "string" && v.trim().length > 0 ? v.trim() : undefined;
122	  } catch {
123	    return undefined;
124	  }
125	}
126	
127	function buildAdapterCapabilities(adapter: ServerAdapterModule): AdapterCapabilities {
128	  return {
129	    supportsInstructionsBundle: adapter.supportsInstructionsBundle ?? false,
130	    supportsSkills: Boolean(adapter.listSkills || adapter.syncSkills),
131	    supportsLocalAgentJwt: adapter.supportsLocalAgentJwt ?? false,
132	    requiresMaterializedRuntimeSkills: adapter.requiresMaterializedRuntimeSkills ?? false,
133	  };
134	}
135	
136	function buildAdapterInfo(adapter: ServerAdapterModule, externalRecord: AdapterPluginRecord | undefined, disabledSet: Set<string>): AdapterInfo {
137	  const fromDisk = externalRecord ? readAdapterPackageVersionFromDisk(externalRecord) : undefined;
138	  return {
139	    type: adapter.type,
140	    label: adapter.type, // ServerAdapterModule doesn't have a separate "label" field; type serves as label
141	    source: externalRecord ? "external" : "builtin",
142	    modelsCount: (adapter.models ?? []).length,
143	    loaded: true, // If it's in the registry, it's loaded
144	    disabled: disabledSet.has(adapter.type),
145	    capabilities: buildAdapterCapabilities(adapter),
146	    overriddenBuiltin: externalRecord ? BUILTIN_ADAPTER_TYPES.has(adapter.type) : undefined,
147	    overridePaused: BUILTIN_ADAPTER_TYPES.has(adapter.type) ? isOverridePaused(adapter.type) : undefined,
148	    // Prefer on-disk package.json so the UI reflects bumps without relying on store-only fields.
149	    version: fromDisk ?? externalRecord?.version,
150	    packageName: externalRecord?.packageName,
151	    isLocalPath: externalRecord?.localPath ? true : undefined,
152	  };
153	}
154	
155	/**
156	 * Normalize a local path that may be a Windows path into a WSL-compatible path.
157	 *
158	 * - Windows paths (e.g., "C:\\Users\\...") are converted via `wslpath -u`.
159	 * - Paths already starting with `/mnt/` or `/` are returned as-is.
160	 */
161	async function normalizeLocalPath(rawPath: string): Promise<string> {
162	  // Already a POSIX path (WSL or native Linux)
163	  if (rawPath.startsWith("/")) {
164	    return rawPath;
165	  }
166	
167	  // Windows path detection: C:\ or C:/ pattern
168	  if (/^[A-Za-z]:[\\/]/.test(rawPath)) {
169	    try {
170	      const { stdout } = await execFileAsync("wslpath", ["-u", rawPath]);
171	      return stdout.trim();
172	    } catch (err) {
173	      logger.warn({ err, rawPath }, "wslpath conversion failed; using path as-is");
174	      return rawPath;
175	    }
176	  }
177	
178	  return rawPath;
179	}
180	
181	/**
182	 * Register an external adapter module into the server registry via the
183	 * hot-install path, resolving `sessionManagement` identically to how the
184	 * init-time IIFE does. Module-provided `sessionManagement` is honored first,
185	 * with fallback to the host registry by type for builtin-type overrides.
186	 *
187	 * Keeps the hot-install and init-time paths at parity so an adapter installed
188	 * via `POST /api/adapters/install` has the same shape in the registry as the
189	 * same adapter loaded on the next server restart.
190	 */
191	function registerWithSessionManagement(adapter: ServerAdapterModule): void {
192	  registerServerAdapter(resolveExternalAdapterRegistration(adapter));
193	}
194	
195	// ---------------------------------------------------------------------------
196	// Router
197	// ---------------------------------------------------------------------------
198	
199	export function adapterRoutes() {
200	  const router = Router();
201	
202	  // Storage is not used by any adapter handler.
203	  const storageSentinel = new Proxy({} as StorageService, {
204	    get(_target, prop) {
205	      throw new Error(`adapter handler unexpectedly accessed storage.${String(prop)}`);
206	    },
207	  });
208	
209	  // A placeholder Db sentinel — adapter routes do not touch the database.
210	  // expressHandler requires a Db in deps; supply a proxy that throws on access.
211	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
212	  const dbSentinel = new Proxy({} as any, {
213	    get(_target, prop) {
214	      throw new Error(`adapter handler unexpectedly accessed db.${String(prop)}`);
215	    },
216	  });
217	
218	  const adapterDeps = { db: dbSentinel, storage: storageSentinel };
219	
220	  // ---------------------------------------------------------------------------
221	  // Authz helpers
222	  // ---------------------------------------------------------------------------
223	
224	  function assertBoardOrgAccessCtx(ctx: import("../http/types.js").RequestCtx) {
225	    if (!ctx.actor || ctx.actor.type !== "board") {
226	      throw forbidden("Board access required");
227	    }
228	  }
229	
230	  function assertInstanceAdminCtx(ctx: import("../http/types.js").RequestCtx) {
231	    if (!ctx.actor || ctx.actor.type !== "board") {
232	      throw forbidden("Instance admin access required");
233	    }
234	    // The richer isInstanceAdmin flag lives on the Express req.actor but is not
235	    // available in the minimal ActorContext. The expressHandler bridge runs the
236	    // full Express middleware chain first (including auth) so instance-admin
237	    // checks that depend on req.actor.isInstanceAdmin are enforced at the
238	    // Express layer via assertInstanceAdmin(req). Here we just ensure
239	    // board-level authentication as a baseline.
240	  }
241	
242	  // config schema cache shared across the router's lifetime
243	  const configSchemaCache = new Map<string, {
244	    adapter: ServerAdapterModule;
245	    schema: AdapterConfigSchema;
246	    fetchedAt: number;
247	  }>();
248	  const CONFIG_SCHEMA_TTL_MS = 30_000;
249	
250	  /**
251	   * GET /api/adapters
252	   *
253	   * List all registered adapters (built-in + external).
254	   * Each entry includes whether the adapter is built-in or external,
255	   * its model count, and load status.
256	   */
257	  const listAdapters: Handler = async (ctx) => {
258	    assertBoardOrgAccessCtx(ctx);
259	
260	    const registeredAdapters = listServerAdapters();
261	    const externalRecords = new Map(
262	      listAdapterPlugins().map((r) => [r.type, r]),
263	    );
264	    const disabledSet = new Set(getDisabledAdapterTypes());
265	
266	    const result: AdapterInfo[] = registeredAdapters.map((adapter) =>
267	      buildAdapterInfo(adapter, externalRecords.get(adapter.type), disabledSet),
268	    ).sort((a, b) => a.type.localeCompare(b.type));
269	
270	    return Response.json(result);
271	  };
272	
273	  /**
274	   * POST /api/adapters/install
275	   *
276	   * Install an external adapter from an npm package or local path.
277	   *
278	   * Request body:
279	   * - packageName: string (required) — npm package name or local path
280	   * - isLocalPath?: boolean (default false)
281	   * - version?: string — target version for npm packages
282	   */
283	  const installAdapter: Handler = async (ctx) => {
284	    // Instance-admin check is enforced by the Express assertInstanceAdmin
285	    // middleware wired before this handler in the route definition below.
286	
287	    const body = await ctx.json<AdapterInstallRequest>();
288	    const { packageName, isLocalPath = false, version } = body;
289	
290	    if (!packageName || typeof packageName !== "string") {
291	      return Response.json({ error: "packageName is required and must be a string." }, { status: 400 });
292	    }
293	
294	    // Strip version suffix if the UI sends "pkg@1.2.3" instead of separating it
295	    let canonicalName = packageName;
296	    let explicitVersion = version;
297	    const versionSuffix = packageName.match(/@(\d+\.\d+\.\d+.*)$/);
298	    if (versionSuffix) {
299	      const lastAtIndex = packageName.lastIndexOf("@");
300	      if (lastAtIndex > 0 && !explicitVersion) {
301	        canonicalName = packageName.slice(0, lastAtIndex);
302	        explicitVersion = versionSuffix[1];
303	      }
304	    }
305	
306	    try {
307	      let installedVersion: string | undefined;
308	      let moduleLocalPath: string | undefined;
309	
310	      if (!isLocalPath) {
311	        const pluginsDir = getAdapterPluginsDir();
312	        const spec = explicitVersion ? `${canonicalName}@${explicitVersion}` : canonicalName;
313	
314	        logger.info({ spec, pluginsDir }, "Installing adapter package via npm");
315	
316	        await execFileAsync("npm", ["install", "--no-save", spec], {
317	          cwd: pluginsDir,
318	          timeout: 120_000,
319	        });
320	
321	        // TODO(cloudflare): reading package.json from the npm install directory
322	        // uses node:fs/promises at request time. For Workers compatibility the
323	        // installed version should be persisted to the DB by the install job and
324	        // read from there rather than from the local filesystem.
325	        try {
326	          const pkgJsonPath = path.join(pluginsDir, "node_modules", canonicalName, "package.json");
327	          const pkgContent = await import("node:fs/promises");
328	          const pkgRaw = await pkgContent.readFile(pkgJsonPath, "utf-8");
329	          const pkg = JSON.parse(pkgRaw);
330	          const v = pkg.version;
331	          installedVersion =
332	            typeof v === "string" && v.trim().length > 0 ? v.trim() : explicitVersion;
333	        } catch {
334	          installedVersion = explicitVersion;
335	        }
336	      } else {
337	        moduleLocalPath = path.resolve(await normalizeLocalPath(packageName));
338	        // TODO(cloudflare): reading package.json from a local-path adapter
339	        // directory uses node:fs/promises at request time. For Workers
340	        // compatibility the version should be captured during the install step
341	        // and stored in the database rather than read from disk at request time.
342	        try {
343	          const pkgRaw = await readFile(path.join(moduleLocalPath, "package.json"), "utf-8");
344	          const v = JSON.parse(pkgRaw).version;
345	          if (typeof v === "string" && v.trim().length > 0) {
346	            installedVersion = v.trim();
347	          }
348	        } catch {
349	          // leave installedVersion undefined if package.json is missing
350	        }
351	      }
352	
353	      const adapterModule = await loadExternalAdapterPackage(canonicalName, moduleLocalPath);
354	
355	      if (BUILTIN_ADAPTER_TYPES.has(adapterModule.type)) {
356	        return Response.json({
357	          error: `Adapter type "${adapterModule.type}" is a built-in adapter and cannot be overwritten.`,
358	        }, { status: 409 });
359	      }
360	
361	      const existing = findServerAdapter(adapterModule.type);
362	      const isReinstall = existing !== null;
363	      if (existing) {
364	        unregisterServerAdapter(adapterModule.type);
365	        logger.info({ type: adapterModule.type }, "Unregistered existing adapter for replacement");
366	      }
367	
368	      registerWithSessionManagement(adapterModule);
369	
370	      const record: AdapterPluginRecord = {
371	        packageName: canonicalName,
372	        localPath: moduleLocalPath,
373	        version: installedVersion ?? explicitVersion,
374	        type: adapterModule.type,
375	        installedAt: new Date().toISOString(),
376	      };
377	      addAdapterPlugin(record);
378	
379	      logger.info(
380	        { type: adapterModule.type, packageName: canonicalName },
381	        "External adapter installed and registered",
382	      );
383	
384	      return Response.json({
385	        type: adapterModule.type,
386	        packageName: canonicalName,
387	        version: installedVersion ?? explicitVersion,
388	        installedAt: record.installedAt,
389	        requiresRestart: isReinstall,
390	      }, { status: 201 });
391	    } catch (err) {
392	      const message = err instanceof Error ? err.message : String(err);
393	      logger.error({ err, packageName }, "Failed to install external adapter");
394	
395	      if (message.includes("npm") || message.includes("ERR!")) {
396	        return Response.json({ error: `npm install failed: ${message}` }, { status: 500 });
397	      }
398	      return Response.json({ error: `Failed to install adapter: ${message}` }, { status: 500 });
399	    }
400	  };
401	
402	  /**
403	   * PATCH /api/adapters/:type
404	   *
405	   * Enable or disable an adapter.
406	   *
407	   * Request body: { "disabled": boolean }
408	   */
409	  const patchAdapter: Handler = async (ctx) => {
410	    const adapterType = ctx.param("type");
411	    if (!adapterType) return Response.json({ error: "Adapter type is required." }, { status: 400 });
412	    const body = await ctx.json<{ disabled?: boolean }>();
413	    const { disabled } = body;
414	
415	    if (typeof disabled !== "boolean") {
416	      return Response.json({ error: "Request body must include { \"disabled\": true|false }." }, { status: 400 });
417	    }
418	
419	    const existing = findServerAdapter(adapterType);
420	    if (!existing) {
421	      return Response.json({ error: `Adapter "${adapterType}" is not registered.` }, { status: 404 });
422	    }
423	
424	    const changed = setAdapterDisabled(adapterType, disabled);
425	
426	    if (changed) {
427	      logger.info({ type: adapterType, disabled }, "Adapter enabled/disabled");
428	    }
429	
430	    return Response.json({ type: adapterType, disabled, changed });
431	  };
432	
433	  /**
434	   * PATCH /api/adapters/:type/override
435	   *
436	   * Pause or resume an external adapter's override of a builtin type.
437	   */
438	  const patchAdapterOverride: Handler = async (ctx) => {
439	    const adapterType = ctx.param("type");
440	    if (!adapterType) return Response.json({ error: "Adapter type is required." }, { status: 400 });
441	    const body = await ctx.json<{ paused?: boolean }>();
442	    const { paused } = body;
443	
444	    if (typeof paused !== "boolean") {
445	      return Response.json({ error: "\"paused\" (boolean) is required in request body." }, { status: 400 });
446	    }
447	
448	    if (!BUILTIN_ADAPTER_TYPES.has(adapterType)) {
449	      return Response.json({ error: `Type "${adapterType}" is not a builtin adapter.` }, { status: 400 });
450	    }
451	
452	    const changed = setOverridePaused(adapterType, paused);
453	
454	    logger.info({ type: adapterType, paused, changed }, "Adapter override toggle");
455	
456	    return Response.json({ type: adapterType, paused, changed });
457	  };
458	
459	  /**
460	   * DELETE /api/adapters/:type
461	   *
462	   * Unregister an external adapter. Built-in adapters cannot be removed.
463	   */
464	  const deleteAdapter: Handler = async (ctx) => {
465	    const adapterType = ctx.param("type");
466	
467	    if (!adapterType) {
468	      return Response.json({ error: "Adapter type is required." }, { status: 400 });
469	    }
470	
471	    if (BUILTIN_ADAPTER_TYPES.has(adapterType)) {
472	      return Response.json({
473	        error: `Cannot remove built-in adapter "${adapterType}".`,
474	      }, { status: 403 });
475	    }
476	
477	    const existing = findServerAdapter(adapterType);
478	    if (!existing) {
479	      return Response.json({
480	        error: `Adapter "${adapterType}" is not registered.`,
481	      }, { status: 404 });
482	    }
483	
484	    const externalRecord = getAdapterPluginByType(adapterType);
485	    if (!externalRecord) {
486	      return Response.json({
487	        error: `Adapter "${adapterType}" is not an externally installed adapter.`,
488	      }, { status: 404 });
489	    }
490	
491	    if (externalRecord.packageName && !externalRecord.localPath) {
492	      try {
493	        const pluginsDir = getAdapterPluginsDir();
494	        await execFileAsync("npm", ["uninstall", externalRecord.packageName], {
495	          cwd: pluginsDir,
496	          timeout: 60_000,
497	        });
498	        logger.info(
499	          { type: adapterType, packageName: externalRecord.packageName },
500	          "npm uninstall completed for external adapter",
501	        );
502	      } catch (err) {
503	        logger.warn(
504	          { err, type: adapterType, packageName: externalRecord.packageName },
505	          "npm uninstall failed for external adapter; continuing with unregister",
506	        );
507	      }
508	    }
509	
510	    unregisterServerAdapter(adapterType);
511	    removeAdapterPlugin(adapterType);
512	
513	    logger.info({ type: adapterType }, "External adapter unregistered and removed");
514	
515	    return Response.json({ type: adapterType, removed: true });
516	  };
517	
518	  /**
519	   * POST /api/adapters/:type/reload
520	   *
521	   * Reload an external adapter at runtime.
522	   */
523	  const reloadAdapter: Handler = async (ctx) => {
524	    const type = ctx.param("type");
525	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
526	
527	    if (BUILTIN_ADAPTER_TYPES.has(type) && !getAdapterPluginByType(type)) {
528	      return Response.json({ error: "Cannot reload built-in adapter." }, { status: 400 });
529	    }
530	
531	    try {
532	      const newModule = await reloadExternalAdapter(type);
533	
534	      if (!newModule) {
535	        return Response.json({ error: `Adapter "${type}" is not an externally installed adapter.` }, { status: 404 });
536	      }
537	
538	      unregisterServerAdapter(type);
539	      registerWithSessionManagement(newModule);
540	      configSchemaCache.delete(type);
541	
542	      const record = getAdapterPluginByType(type);
543	      let newVersion: string | undefined;
544	      if (record) {
545	        newVersion = readAdapterPackageVersionFromDisk(record);
546	        if (newVersion) {
547	          addAdapterPlugin({ ...record, version: newVersion });
548	        }
549	      }
550	
551	      logger.info({ type, version: newVersion }, "External adapter reloaded at runtime");
552	
553	      return Response.json({ type, version: newVersion, reloaded: true });
554	    } catch (err) {
555	      const message = err instanceof Error ? err.message : String(err);
556	      logger.error({ err, type }, "Failed to reload external adapter");
557	      return Response.json({ error: `Failed to reload adapter: ${message}` }, { status: 500 });
558	    }
559	  };
560	
561	  /**
562	   * POST /api/adapters/:type/reinstall
563	   *
564	   * Reinstall an npm-sourced external adapter.
565	   */
566	  const reinstallAdapter: Handler = async (ctx) => {
567	    const type = ctx.param("type");
568	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
569	
570	    if (BUILTIN_ADAPTER_TYPES.has(type) && !getAdapterPluginByType(type)) {
571	      return Response.json({ error: "Cannot reinstall built-in adapter." }, { status: 400 });
572	    }
573	
574	    const record = getAdapterPluginByType(type);
575	    if (!record) {
576	      return Response.json({ error: `Adapter "${type}" is not an externally installed adapter.` }, { status: 404 });
577	    }
578	
579	    if (record.localPath) {
580	      return Response.json({ error: "Local-path adapters cannot be reinstalled. Use Reload instead." }, { status: 400 });
581	    }
582	
583	    try {
584	      const pluginsDir = getAdapterPluginsDir();
585	
586	      logger.info({ type, packageName: record.packageName }, "Reinstalling adapter package via npm");
587	
588	      await execFileAsync("npm", ["install", "--no-save", record.packageName], {
589	        cwd: pluginsDir,
590	        timeout: 120_000,
591	      });
592	
593	      const newModule = await reloadExternalAdapter(type);
594	      if (!newModule) {
595	        return Response.json({ error: "npm install succeeded but adapter reload failed." }, { status: 500 });
596	      }
597	
598	      unregisterServerAdapter(type);
599	      registerWithSessionManagement(newModule);
600	      configSchemaCache.delete(type);
601	
602	      let newVersion: string | undefined;
603	      const updatedRecord = getAdapterPluginByType(type);
604	      if (updatedRecord) {
605	        newVersion = readAdapterPackageVersionFromDisk(updatedRecord);
606	        if (newVersion) {
607	          addAdapterPlugin({ ...updatedRecord, version: newVersion });
608	        }
609	      }
610	
611	      logger.info({ type, version: newVersion }, "Adapter reinstalled from npm");
612	
613	      return Response.json({ type, version: newVersion, reinstalled: true });
614	    } catch (err) {
615	      const message = err instanceof Error ? err.message : String(err);
616	      logger.error({ err, type }, "Failed to reinstall adapter");
617	      return Response.json({ error: `Reinstall failed: ${message}` }, { status: 500 });
618	    }
619	  };
620	
621	  /**
622	   * GET /api/adapters/:type/config-schema
623	   *
624	   * Serve a declarative config schema for an adapter's UI form fields.
625	   */
626	  const getAdapterConfigSchema: Handler = async (ctx) => {
627	    assertBoardOrgAccessCtx(ctx);
628	    const type = ctx.param("type");
629	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
630	
631	    const adapter = findActiveServerAdapter(type);
632	    if (!adapter) {
633	      return Response.json({ error: `Adapter "${type}" is not registered.` }, { status: 404 });
634	    }
635	    if (!adapter.getConfigSchema) {
636	      return Response.json({ error: `Adapter "${type}" does not provide a config schema.` }, { status: 404 });
637	    }
638	
639	    const cached = configSchemaCache.get(type);
640	    if (cached && cached.adapter === adapter && Date.now() - cached.fetchedAt < CONFIG_SCHEMA_TTL_MS) {
641	      return Response.json(cached.schema);
642	    }
643	
644	    try {
645	      const schema = await adapter.getConfigSchema();
646	      configSchemaCache.set(type, { adapter, schema, fetchedAt: Date.now() });
647	      return Response.json(schema);
648	    } catch (err) {
649	      const message = err instanceof Error ? err.message : String(err);
650	      logger.error({ err, type }, "Failed to resolve config schema");
651	      return Response.json({ error: `Failed to resolve config schema: ${message}` }, { status: 500 });
652	    }
653	  };
