656	   * GET /api/adapters/:type/ui-parser.js
657	   *
658	   * Serve the self-contained UI parser JS for an adapter type.
659	   */
660	  const getAdapterUiParser: Handler = async (ctx) => {
661	    assertBoardOrgAccessCtx(ctx);
662	    const type = ctx.param("type");
663	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
664	    const source = getOrExtractUiParserSource(type);
665	    if (!source) {
666	      return Response.json({ error: `No UI parser available for adapter "${type}".` }, { status: 404 });
667	    }
668	    return new Response(source, {
669	      headers: { "Content-Type": "application/javascript" },
670	    });
671	  };
